; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			jr ntc_start2
ntc_bk_sp:		dw 0			; #0042: main RAM's SP while a bank runs
ntc_bk_out:
			out (c), c		; #0044: BC = the other side's RAM setting
			jp ntc_bk_land		; #0046: main RAM switched in
ntc_bk_land:
			ld sp, (ntc_bk_sp)
			ret				; to where main RAM handed over
			ASSERT ntc_bk_out == #0044, "the bank switch must be at #0044"
ntc_start2:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 21: Print "VB test 3"
			dw kw_printstrvar, str0
			dw kw_printnl

			; 22: Chk Red, 0
			dw p_chk_c, lit_0, lit_0

			; 23: Chk Green, 5
			dw p_chk_c, lit_5, lit_5

			; 24: Chk Blue, 6
			dw p_chk_c, lit_6, lit_6

			; 25: Chk Colour.Blue + Size.Large, 16
			dw p_chk_c, lit_16, lit_16

			; 26: c = Green
			dw kw_ltov, 5, var_c

			; 27: Chk c, 5
			dw p_chk_c, var_c, lit_5

			; 29: .w = 3
			dw kw_ltov, 3, var_b_w

			; 30: .h = 4
			dw kw_ltov, 4, var_b_h

			; 31: .label = "box"
			dw kw_strcpy, var_b_label, str1

			; 32: n = .w * .h
			dw kw_mulvv, var_b_w, var_b_h, var_n

			; 34: Chk n, 12
			dw p_chk_c, var_n, lit_12

			; 35: ChkS b.label, "box"
			dw p_chks_c, var_b_label, str1

			; 36: For i = 0 To 2
			dw kw_ztov, var_i
for1_t:

			; 38: .w = i
			dw kw_aset, arr_boxes_w, var_i, var_i

			; 39: .h = i * 2
			dw kw_2x, var_i, tmp1
			dw kw_aset, arr_boxes_h, var_i, tmp1

			; 41: Next
			dw kw_next1l_n, var_i, 2, for1_t
for1_e:

			; 42: Chk boxes(2).w + boxes(2).h, 6
			dw kw_add, arr_boxes_w+4, arr_boxes_h+4, tmp0
			dw p_chk_c, tmp0, lit_6

			; 43: n = 0
			dw kw_ztov, var_n

			; 44: For i = 1 To 3
			dw kw_ltov, 1, var_i
for2_t:

			; 45: On i GoSub one, two, three
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iffalse_n, on3_0
			dw lbl_one_gs
			dw on3_e_go
on3_0:
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iffalse_n, on3_1
			dw lbl_two_gs
			dw on3_e_go
on3_1:
			dw kw_cpeqvl, var_i, 3
			dw kw_goto_iffalse_n, on3_2
			dw lbl_three_gs
on3_2:
on3_e:

			; 46: Next
			dw kw_next1l_n, var_i, 3, for2_t
for2_e:

			; 47: Chk n, 321
			dw p_chk_c, var_n, lit_321

			; 48: i = 2
			dw kw_ltov, 2, var_i

			; 49: On i GoTo l1, l2
			dw kw_cpeqvl, var_i, 1
			dw kw_goto_iftrue_n, lbl_l1
			dw kw_cpeqvl, var_i, 2
			dw kw_goto_iftrue_n, lbl_l2

			; 50: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 51: l1:
lbl_l1:

			; 52: Chk 0, 1
			dw p_chk_c, lit_0, lit_1

			; 53: l2:
lbl_l2:

			; 54: Chk 1, 1
			dw p_chk_c, lit_1, lit_1

			; 55: k = Inkey$
			dw kw_inkeys, stmp0
			dw kw_strcpy, var_k, stmp0

			; 56: ChkS k, ""
			dw p_chks_c, var_k, str2

			; 57: Print
			dw kw_printnl

			; 58: Print t; " tests, "; bad; " failed"
			dw kw_printint, var_t
			dw kw_printstrvar, str3
			dw kw_printint, var_bad
			dw kw_printstrvar, str4
			dw kw_printnl

			; 59: End
			dw kw_printnl0
			dw kw_printstrvar, str5
			dw kw_waitkey
			dw kw_stop

			; 60: one:
lbl_one:

			; 61: n = n + 1
			dw kw_inc, var_n

			; 62: Return
			dw lbl_one_rt

			; 63: two:
lbl_two:

			; 64: n = n + 20
			dw kw_addl, var_n, 20, var_n

			; 65: Return
			dw lbl_two_rt

			; 66: three:
lbl_three:

			; 67: n = n + 300
			dw kw_addl, var_n, 300, var_n

			; 68: Return
			dw lbl_three_rt

; ============================================================
; sub chk (normal mode)
; ============================================================

p_chk:

			; 71: t = t + 1
			dw kw_inc, var_t

			; 72: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 73: If got = want Then Print "ok "; Else Print "FAIL("; got; ") "; : bad = bad + 1
			dw kw_cpeqvv, var_chk_got, var_chk_want
			dw kw_goto_iffalse_n, if5_1
			dw kw_printstrvar, str7
			dw if5_e_go
if5_1:
			dw kw_printstrvar, str8
			dw kw_printint, var_chk_got
			dw kw_printstrvar, str9
			dw kw_inc, var_bad
if5_e:
			dw p_chk_r

; ============================================================
; sub chks (normal mode)
; ============================================================

p_chks:

			; 77: t = t + 1
			dw kw_inc, var_t

			; 78: Print t; ":";
			dw kw_printint, var_t
			dw kw_printstrvar, str6

			; 79: If got = want Then Print "ok "; Else Print "FAIL["; got; "] "; : bad = bad + 1
			dw kw_strcmpeq, var_chks_got, var_chks_want
			dw kw_goto_iffalse_n, if6_1
			dw kw_printstrvar, str7
			dw if6_e_go
if6_1:
			dw kw_printstrvar, str10
			dw kw_printstrvar, var_chks_got
			dw kw_printstrvar, str11
			dw kw_inc, var_bad
if6_e:
			dw p_chks_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

on3_e_go:			ld sp, on3_e
			jp ntc_xn
if5_e_go:			ld sp, if5_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
lbl_one_gs:			ld (lbl_one_rs), sp
			ld sp, lbl_one
			jp ntc_xn
lbl_one_rt:			ld sp, (lbl_one_rs)
			jp ntc_xn
lbl_two_gs:			ld (lbl_two_rs), sp
			ld sp, lbl_two
			jp ntc_xn
lbl_two_rt:			ld sp, (lbl_two_rs)
			jp ntc_xn
lbl_three_gs:			ld (lbl_three_rs), sp
			ld sp, lbl_three
			jp ntc_xn
lbl_three_rt:			ld sp, (lbl_three_rs)
			jp ntc_xn

p_chk_c:		; call chk (normal)
			pop hl			; got
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_got), de
			pop hl			; want
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (var_chk_want), de
			ld (p_chk_rs), sp
			ld sp, p_chk
			jp ntc_xn
p_chk_r:		; end of chk
			ld sp, (p_chk_rs)
			jp ntc_xn
p_chks_c:		; call chks (normal)
			pop hl			; got
			ld de, var_chks_got
			ld b, 255
p_chks_si0:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si0_e
			inc hl
			inc de
			djnz p_chks_si0
			xor a
			ld (de), a
p_chks_si0_e:
			pop hl			; want
			ld de, var_chks_want
			ld b, 255
p_chks_si1:
			ld a, (hl)
			ld (de), a
			or a
			jr z, p_chks_si1_e
			inc hl
			inc de
			djnz p_chks_si1
			xor a
			ld (de), a
p_chks_si1_e:
			ld (p_chks_rs), sp
			ld sp, p_chks
			jp ntc_xn
p_chks_r:		; end of chks
			ld sp, (p_chks_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_c:			dw 0
var_b_w:			dw 0
var_b_h:			dw 0
			db 40			; capacity
var_b_label:			ds 41
var_n:			dw 0
var_i:			dw 0
			db 40			; capacity
var_k:			ds 41
var_t:			dw 0
var_bad:			dw 0
p_chk_rs:			dw 0
var_chk_got:			dw 0
var_chk_want:			dw 0
p_chks_rs:			dw 0
			db 255			; capacity
var_chks_got:			ds 256
			db 255			; capacity
var_chks_want:			ds 256
lbl_one_rs:			dw 0
lbl_two_rs:			dw 0
lbl_three_rs:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256

; numbers passed by address (read only)
lit_0:			dw 0
lit_5:			dw 5
lit_6:			dw 6
lit_16:			dw 16
lit_12:			dw 12
lit_321:			dw 321
lit_1:			dw 1

; ============================================================
; Strings
; ============================================================

str0:			db "VB test 3", 0
str1:			db "box", 0
str2:			db 0
str3:			db " tests, ", 0
str4:			db " failed", 0
str5:			db "Press a key", 0
str6:			db ":", 0
str7:			db "ok ", 0
str8:			db "FAIL(", 0
str9:			db ") ", 0
str10:			db "FAIL[", 0
str11:			db "] ", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_ztov:		jp 49
kw_inc:		jp 51
kw_add:		jp 53
kw_addl:		jp 54
kw_2x:		jp 57
kw_mulvv:	jp 60
kw_cpeqvv:	jp 95
kw_cpeqvl:	jp 96
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcmpeq:	jp 126
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl0:	jp 134
kw_printnl:	jp 138
kw_inkeys:	jp 145
kw_bssinit:	jp 288
kw_waitkey:	jp 348
NTC_RJ_N	equ 24		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_v_free	equ #894E		; ROM data
ntc_v_romen	equ #8954		; ROM data
ntc_v_romold	equ #8956		; ROM data
ntc_v_stamp	equ #8952		; ROM data
ntc_v_start	equ #8950		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)


; the start code (Library: ROM): run once, then the arrays go over it
ntc_rj_drop:
; the start: find the ROM set in slots 0 - 31 (its main ROM, then the others with the same
; stamp), have the main one patch the jump block. NC = ready; C = not there / too old
; (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			xor a
			ld (ntc_rj_want), a
			call ntc_rj_scan		; the main ROM
			jp c, ntc_rj_nf
			ld (ntc_rj_slots), a
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, 1
ntc_rj_more:				; the other ROMs of the set
			ld (ntc_rj_want), a
			ld hl, ntc_rj_n
			cp (hl)
			jr nc, ntc_rj_all
			call ntc_rj_scan
			jp c, ntc_rj_part
			ld b, a
			ld a, (ntc_rj_want)
			ld e, a
			ld d, 0
			ld hl, ntc_rj_slots
			add hl, de
			ld (hl), b
			inc a
			jr ntc_rj_more
ntc_rj_all:
			ld a, (ntc_rj_slots)
			ld c, a
			call #B90F		; KL ROM SELECT: the main ROM
			di					; (KL ROM SELECT lets interrupts in)
			ld a, (ntc_rj_slots)	; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
			ld de, ntc_rj_slots
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot, DE = slots; C: DE = a number it hasn't got
			jp c, ntc_rj_lacks
			IF (ntc_bss >= 32768) && (ntc_bssfrom <= 16384)	; fwdref-ok
			ld hl, ntc_bssfrom		; (the end of the program - or this start code, which tables may go over)
			ELSE
			ld hl, ntc_free
			ENDIF
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
; ntc_rj_scan - a ROM of the set: ROM ntc_rj_want (0 = the main one, any stamp; the others
; with the main one's stamp). NC: A = its slot, HL = past its block's count byte (the main
; one: at its patcher), it is selected. C: not there
ntc_rj_scan:
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; DE = its set's stamp
			inc hl
			ld a, (ntc_rj_want)
			cp (hl)				; its place in the set
			jr nz, ntc_rj_skip
			or a
			jr z, ntc_rj_got
			push hl
			ld hl, (ntc_rj_set)
			or a
			sbc hl, de
			pop hl
			jr nz, ntc_rj_skip		; another build's
ntc_rj_got:
			ld (ntc_rj_set), de
			inc hl
			ld a, (hl)
			ld (ntc_rj_n), a		; ROMs in the set
			inc hl
			ld a, c
			or a				; NC
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			scf					; C: not there
			ret
ntc_rj_nf:
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_part:				; a ROM of the set is missing: its number (1 = the main one)
			ld a, (ntc_rj_want)
			inc a
			ld e, a
			ld d, 0
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tpt
			jr ntc_rj_fnum
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fnum:
			ld a, 1
			ld (ntc_rj_pn), a		; the number after the message
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld a, (ntc_rj_pn)
			or a
			jr z, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
ntc_rj_num:		dw 0
ntc_rj_pn:		db 0			; 1 = a number goes after the message
ntc_rj_want:	db 0			; the ROM of the set looked for
ntc_rj_n:		db 1			; ROMs in the set
ntc_rj_set:		dw 0			; the set's stamp
ntc_rj_slots:	ds 8			; each ROM's slot, the main one first
ntc_rj_sig:		db "NTC", 2, "CPCFW", 0	; the ROMs' NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tpt:		db "ROM NTCFW<n>.ROM not found: n = #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0
ntc_rj_dropend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
			IF ntc_rj_dropend == ntc_end	; fwdref-ok
ntc_bssfrom	equ ntc_rj_drop		; the arrays over the start code (it has run)
			ELSE
ntc_bssfrom	equ ntc_end
			ENDIF
ntc_bss		equ ntc_bssfrom
arr_boxes		equ ntc_bss + 0		; 6 bytes
arr_boxes_w		equ ntc_bss + 6		; 6 bytes
arr_boxes_h		equ ntc_bss + 12		; 6 bytes
ntc_bss_size	equ 18
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			SAVEAMSDOS "VBTEST3.BIN", ntc_start, ntc_end - ntc_start, ntc_start
